"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["23870"],{39763(a){a.exports=JSON.parse('{"tag":{"label":"mental health","permalink":"/docs/tags/mental-health","allTagsPath":"/docs/tags","count":10,"items":[{"id":"general-care/daily-care/playing-and-training","title":"Playing & Training Your Small Pet","description":"All small pets benefit from play, enrichment, and mental stimulation. Learn how to engage your pet\'s natural instincts through species-appropriate play, foraging, and positive-reinforcement training.","permalink":"/docs/general-care/daily-care/playing-and-training"},{"id":"Chinchillas/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Chinchilla","description":"Chinchillas are active, athletic animals that need daily out-of-cage time and enrichment. Learn how to safely play with and train your chinchilla.","permalink":"/docs/Chinchillas/care-and-husbandry/playing-and-training"},{"id":"Degus/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Degus","description":"Degus are highly social, intelligent animals that need daily enrichment and interaction. Learn how to play with and train your degus using positive reinforcement.","permalink":"/docs/Degus/care-and-husbandry/playing-and-training"},{"id":"Ferrets/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Ferret","description":"Ferrets are highly playful, mischievous animals that need several hours of out-of-cage time and enrichment daily. Learn how to play with and train your ferret.","permalink":"/docs/Ferrets/care-and-husbandry/playing-and-training"},{"id":"Gerbils/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Gerbil","description":"Gerbils are active, social, and surprisingly trainable. Learn how to enrich your gerbils\' environment and teach them simple behaviors using positive reinforcement.","permalink":"/docs/Gerbils/care-and-husbandry/playing-and-training"},{"id":"guinea-pigs/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Guinea Pig","description":"Guinea pigs are social, curious animals that thrive with daily enrichment and gentle training. Learn how to engage your guinea pig\'s natural instincts through play and positive reinforcement.","permalink":"/docs/guinea-pigs/care-and-husbandry/playing-and-training"},{"id":"Hamsters/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Hamster","description":"Hamsters are intelligent, curious animals that need daily enrichment to stay healthy and happy. Learn how to engage your hamster\'s natural instincts and teach simple behaviors.","permalink":"/docs/Hamsters/care-and-husbandry/playing-and-training"},{"id":"Hedgehogs/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Hedgehog","description":"Hedgehogs are solitary, nocturnal explorers that need nightly enrichment and exercise. Learn how to engage your hedgehog\'s natural instincts and build a bond through gentle handling and simple training.","permalink":"/docs/Hedgehogs/care-and-husbandry/playing-and-training"},{"id":"Mice/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Mice","description":"Mice are highly intelligent, social animals that thrive with daily enrichment and positive-reinforcement training. Learn how to engage your mice\'s natural instincts and teach them simple tricks.","permalink":"/docs/Mice/care-and-husbandry/playing-and-training"},{"id":"Rabbits/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Rabbit","description":"Rabbits are intelligent, curious animals that need daily mental and physical stimulation. Learn how to play with and train your rabbit using positive reinforcement.","permalink":"/docs/Rabbits/care-and-husbandry/playing-and-training"}],"unlisted":false}}')}}]);